\item[S2] József Pintér, Nowhere-Zero 4-Flows in Graphs Excluding a Proper Minor of the Petersen Graph, arXiv:2607.22267v2 (2026), abstract and Sections 1--2. \url{https://arxiv.org/pdf/2607.22267v2}.
\end{description}
